@POST
@Produces( { MediaType.APPLICATION_JSON, "application/javascript",
MediaType.APPLICATION_XML })
public Response createSession(@QueryParam("op") String op,
        @QueryParam("expire") @DefaultValue("5") String expire,
        @Context UriInfo ui) {
    if (!op.equals("create")) {
        throw new WebApplicationException(Response.status(Response.Status.BAD_REQUEST)
                .entity(new ZError(ui.getRequestUri().toString(), "")).build());
    }

    int expireInSeconds;

    try {
        expireInSeconds = Integer.parseInt(expire);
    } catch (NumberFormatException e) {
        throw new WebApplicationException(Response.status(Response.Status.BAD_REQUEST).build());
    }

    String uuid = UUID.randomUUID().toString();

    while (ZooKeeperService.isConnected(contextPath, uuid)) {
        uuid = UUID.randomUUID().toString();
    }

    // establish the connection to the ZooKeeper cluster
    try {
        ZooKeeperService.getClient(contextPath, uuid, expireInSeconds);
    } catch (IOException e) {
        LOG.error("Failed while trying to create a new session", e);
        throw new WebApplicationException(Response.status(Response.Status.INTERNAL_SERVER_ERROR).build());
    }

    URI uri = ui.getAbsolutePathBuilder().path(uuid).build();
    return Response.created(uri).entity(new JSONWithPadding(new ZSession(uuid, uri.toString()))).build();
}

public static void addImageToDocument(PDDocument doc, 
PDImageXObject image, String fitOption, 
boolean autoRotate)throws IOException {
    boolean imageIsLandscape = image.getWidth() > image.getHeight();

    PDRectangle pageSize = PDRectangle.A4;

    if (autoRotate && imageIsLandscape) {
        pageSize = new PDRectangle(pageSize.getHeight(), pageSize.getWidth());
    }

    if ("fitDocumentToImage".equals(fitOption)) {
        pageSize = new PDRectangle(image.getWidth(), image.getHeight());
    }

    PDPage page = new PDPage(pageSize);
    doc.addPage(page);

    float pageWidth = page.getMediaBox().getWidth();

    float pageHeight = page.getMediaBox().getHeight();

    try (PDPageContentStream contentStream = 
    new PDPageContentStream(doc, page, AppendMode.APPEND, true, true)) {
        if (!("fillPage".equals(fitOption) || "fitDocumentToImage".equals(fitOption))) {
            if ("maintainAspectRatio".equals(fitOption)) {
                float imageAspectRatio = (float) image.getWidth() / (float) image.getHeight();

                float pageAspectRatio = pageWidth / pageHeight;

                float scaleFactor = 1.0f;

                if (imageAspectRatio > pageAspectRatio) {
                    scaleFactor = pageWidth / image.getWidth();
                } else {
                    scaleFactor = pageHeight / image.getHeight();
                }

                float xPos = (pageWidth - (image.getWidth() * scaleFactor)) / 2;

                float yPos = (pageHeight - (image.getHeight() * scaleFactor)) / 2;
                contentStream.drawImage(image, xPos, yPos, image.getWidth() * scaleFactor, image.getHeight() * scaleFactor);
            }
        } else {
            contentStream.drawImage(image, 0, 0, pageWidth, pageHeight);
        } 
    } catch (IOException e) {
        log.error("Error adding image to PDF", e);
        throw e;
    }
}

private static String normalizeArch(String value) {
